// Quantities below are explicitly synthetic teaching models, never local data.
const finite=(v,name,min,max)=>{if(!Number.isFinite(v)||v<min||v>max)throw Error('Ungültiger Parameter '+name);return v;};
export function growthModel({initial=10,rate=.25,capacity=100,days=20}={}){finite(initial,'N₀',0,1e6);finite(rate,'r / Tag',0,2);finite(capacity,'K',.001,1e7);finite(days,'Tage',1,365);if(!Number.isInteger(days))throw Error('Ganze Modelltage erforderlich.');const rows=[];for(let t=0;t<=days;t++){const exponential=initial*Math.exp(rate*t),logistic=initial===0?0:capacity/(1+(capacity/initial-1)*Math.exp(-rate*t));if(!Number.isFinite(exponential))throw Error('Modellbereich überschritten.');rows.push({t,exponential,logistic});}return {kind:'exponential-logistic',source:'theoretical-model',units:{t:'days',N:'model individuals',rate:'per day',capacity:'model individuals'},parameters:{initial,rate,capacity,days},rows,assumptions:'Closed homogeneous population; r and K constant; not a prediction for rendered animals'};}
export function predatorPreyModel({prey=30,predator=6,a=.5,b=.025,c=.2,d=.01,days=40,disturbance=false}={}){for(const [k,v,min,max]of [['prey',prey,.01,1000],['predator',predator,.01,1000],['a',a,.001,2],['b',b,.0001,.2],['c',c,.001,2],['d',d,.0001,.2],['days',days,1,200]])finite(v,k,min,max);if(!Number.isInteger(days))throw Error('Ganze Modelltage erforderlich.');const dt=.01,rows=[],derivative=(x,y)=>[a*x-b*x*y,d*x*y-c*y];let x=prey,y=predator;for(let step=0;step<=days/dt;step++){if(step%100===0)rows.push({t:step*dt,prey:x,predator:y});if(disturbance&&step===Math.floor(days/dt/2)){x*=.5;y*=.5;}const k1=derivative(x,y),k2=derivative(x+k1[0]*dt/2,y+k1[1]*dt/2),k3=derivative(x+k2[0]*dt/2,y+k2[1]*dt/2),k4=derivative(x+k3[0]*dt,y+k3[1]*dt);x+=dt/6*(k1[0]+2*k2[0]+2*k3[0]+k4[0]);y+=dt/6*(k1[1]+2*k2[1]+2*k3[1]+k4[1]);if(!Number.isFinite(x+y)||x<0||y<0||x+y>1e7)throw Error('Außerhalb des gültigen Modellbereichs.');}return {kind:'lotka-volterra',source:'theoretical-model',parameters:{prey,predator,a,b,c,d,days,disturbance},units:{t:'model days',prey:'model individuals',predator:'model individuals',a:'per day',b:'per predator per day',c:'per day',d:'per prey per day'},rows,assumptions:'Two closed populations; homogeneous encounters; unlimited prey food; no alternative prey, seasons or age structure. Not a fox forecast.'};}
export function toleranceModel({competitor=false}={}){const rows=[];for(let flooding=0;flooding<=24;flooding++){const physiological=Math.exp(-(((flooding-10)/7)**2)),realized=physiological*(competitor?.35+.65*flooding/24:1);rows.push({flooding,physiological,realized});}return {kind:'tolerance',source:'didactic-model',units:{flooding:'hours flooded per model day',physiological:'relative long-term growth',realized:'relative growth with designed competitor'},parameters:{competitor},rows,assumptions:'One-factor long-term model; salinity, substrate and drainage fixed; not calibrated to any marsh species. Transect zoning is not this experiment.'};}
export function carbonModel({days=30,photosynthesis=3,plantRespiration=.8,detritusInput=1,decomposition=.04}={}){finite(days,'Tage',1,365);if(!Number.isInteger(days))throw Error('Ganze Modelltage erforderlich.');finite(photosynthesis,'Photosynthese',0,10);finite(plantRespiration,'Pflanzenatmung',0,10);finite(detritusInput,'Streufluss',0,10);finite(decomposition,'Abbaurate',0,.5);let atmosphere=100,plant=40,litter=20,soil=10;const rows=[];for(let t=0;t<=days;t++){rows.push({t,atmosphere,plant,litter,soil,total:atmosphere+plant+litter+soil});const photo=Math.min(atmosphere,photosynthesis),resp=Math.min(plant+photo,plantRespiration),fall=Math.min(plant+photo-resp,detritusInput),dec=Math.min(litter,decomposition*litter);atmosphere+=-photo+resp+dec*.7;plant+=photo-resp-fall;litter+=fall-dec;soil+=dec*.3;}return {kind:'carbon',source:'didactic-model',units:{t:'model days',pools:'relative carbon units',flows:'relative carbon units per day'},parameters:{days,photosynthesis,plantRespiration,detritusInput,decomposition},rows,assumptions:'Closed carbon balance, explicit atmospheric pool; energy is not conserved as usable energy and not cycled. Soil carbon can later respire; no permanent blue-carbon claim.'};}
export function nitrogenModel({oxygen=true,days=20,input=0}={}){finite(days,'Tage',1,365);if(!Number.isInteger(days))throw Error('Ganze Modelltage erforderlich.');finite(input,'N-Eintrag',0,20);let n2=100,organic=20,ammonium=4,nitrite=0,nitrate=5;const rows=[];for(let t=0;t<=days;t++){rows.push({t,n2,organic,ammonium,nitrite,nitrate,total:n2+organic+ammonium+nitrite+nitrate});if(t===days)break;const fix=Math.min(n2,.4),ammonify=Math.min(organic,.6),nitrify1=oxygen?Math.min(ammonium,.5):0,nitrify2=oxygen?Math.min(nitrite,.4):0,denitrify=oxygen?0:Math.min(nitrate,.35),uptake=Math.min(nitrate,.3);n2+=-fix+denitrify;organic+=fix-ammonify+uptake;ammonium+=ammonify-nitrify1+input;nitrite+=nitrify1-nitrify2;nitrate+=nitrify2-denitrify-uptake;}return {kind:'nitrogen',source:'didactic-model',units:{t:'model days',pools:'relative N units; not mg/l',input:'relative N units per day'},parameters:{oxygen,days,input},rows,processes:['N₂ → organic N: fixation','organic N → NH₄⁺: ammonification','NH₄⁺ → NO₂⁻ → NO₃⁻: aerobic nitrification','NO₃⁻ → N₂: oxygen-limited denitrification'],assumptions:'Explicit forms and atmospheric pool; no quantitative water-quality prediction or instantaneous visible die-off.'};}
export const FOOD_EDGES=Object.freeze([
 ['plant','deer'],['plant','caterpillar'],['plant','bee'],['leaf-litter','earthworm'],['leaf-litter','saprotrophs'],['dead-wood','fomes'],['fomes','saprotrophs'],['earthworm','saprotrophs'],['saprotrophs','CO2'],['plant','CO2'],['CO2','plant'],['aphid','ladybird'],['mouse','fox'],['phytoplankton','cockle'],['diatoms','snail'],['mussel','crab'],['mussel','oystercatcher'],['shrimp','spoonbill']
]);
export const NODE_LABELS={'plant':'Grüne Pflanze','deer':'Reh','caterpillar':'Raupe','bee':'Hummel','leaf-litter':'Totes Blatt','earthworm':'Regenwurm','saprotrophs':'Saprotrophe Mikroorganismen','dead-wood':'Totholz','fomes':'Zunderschwamm','CO2':'Atmosphärisches CO₂','aphid':'Blattlaus','ladybird':'Marienkäfer','mouse':'Waldmaus','fox':'Fuchs','phytoplankton':'Phytoplankton','cockle':'Herzmuschel','diatoms':'Benthische Kieselalgen','snail':'Wattschnecke','mussel':'Miesmuschel','crab':'Strandkrabbe','oystercatcher':'Austernfischer','shrimp':'Garnele','spoonbill':'Löffler'};
export function validNetwork(edges){if(!Array.isArray(edges)||edges.some(e=>!Array.isArray(e)||e.length!==2||!FOOD_EDGES.some(a=>a[0]===e[0]&&a[1]===e[1])))return false;return new Set(edges.map(e=>e.join('>'))).size===edges.length;}
